import XCTest
@testable import RdevCore

/// The v3 one-time pairing derivation, against vectors a THIRD implementation produced.
///
/// `protocol/fixtures/pairing-v3.json` was generated by stdlib Python (hmac/hashlib), so these
/// assertions and the TypeScript ones in `protocol/test/pairing-seed.test.ts` each agree with
/// something neither side wrote. Two implementations that agree only with each other can be wrong
/// together — which is the whole reason cross-implementation fixtures exist in this repo.
final class PairingSeedTests: XCTestCase {

    private struct Case: Decodable {
        let name: String, seed: String, encoded: String, code: String, token: String, psk: String
    }
    private struct Fixture: Decodable { let salt: String, alphabet: String; let cases: [Case] }

    // protocol/fixtures live at repo root, five dirs up from this test file.
    private func fixture() throws -> Fixture {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("protocol/fixtures/pairing-v3.json")
        return try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }

    private func hexBytes(_ s: String) -> [UInt8] {
        stride(from: 0, to: s.count, by: 2).map {
            let i = s.index(s.startIndex, offsetBy: $0)
            return UInt8(s[i ... s.index(after: i)], radix: 16)!
        }
    }

    /// The whole derivation, every vector, all three outputs.
    func testMatchesTheCrossImplementationVectors() throws {
        let f = try fixture()
        XCTAssertEqual(f.salt, PairingSeed.salt, "the fixture and the implementation disagree about the HKDF label")
        XCTAssertEqual(f.alphabet, String(PairingSeed.alphabet))
        XCTAssertFalse(f.cases.isEmpty, "an empty fixture would pass every assertion below")

        for c in f.cases {
            let seed = hexBytes(c.seed)
            let m = try XCTUnwrap(PairingSeed.derive(seed: seed), c.name)
            XCTAssertEqual(m.code, c.code, "code for \(c.name)")
            XCTAssertEqual(m.token, c.token, "token for \(c.name)")
            XCTAssertEqual(m.psk.map { String(format: "%02x", $0) }.joined(), c.psk, "psk for \(c.name)")
            XCTAssertEqual(PairingSeed.encode(seed: seed), c.encoded, "carrier for \(c.name)")
            XCTAssertEqual(PairingSeed.decode(c.encoded), seed, "round trip for \(c.name)")
        }
    }

    /// THE THREE OUTPUTS MUST BE INDEPENDENT. Same seed, different labels: if the `info` argument
    /// were ever dropped or shared, two of these would collide and the psk would be derivable from a
    /// value the Control Plane is given. A length check alone would not notice.
    /// COMPARED AFTER THE SAME ENCODING, which is the only way this can discriminate. An earlier
    /// version compared the code STRING against the psk's HEX — two representations that can never be
    /// equal whatever the bytes underneath, so it passed against a mutant that gave `psk` the `code`
    /// label. Found by mutation, which is what mutation is for.
    func testTheThreeOutputsAreDistinctKeyStreams() throws {
        let m = try XCTUnwrap(PairingSeed.derive(seed: [UInt8](repeating: 7, count: PairingSeed.seedByteCount)))
        let pskAsCode = String(m.psk.prefix(8).map { PairingSeed.alphabet[Int($0) % PairingSeed.alphabet.count] })
        XCTAssertNotEqual(pskAsCode, m.code, "psk and code must not share an HKDF label")
        let pskAsToken = PairingSeed.uuidV4(from: Array(m.psk.prefix(16)))
        XCTAssertNotEqual(pskAsToken, m.token, "psk and token must not share an HKDF label")
    }

    /// A different seed must move every output. Guards against a derivation that ignores its input —
    /// which would pass a fixture test if the fixture had only one case.
    func testEveryOutputDependsOnTheSeed() throws {
        var a = [UInt8](repeating: 0, count: PairingSeed.seedByteCount)
        var b = a; b[PairingSeed.seedByteCount - 1] = 1   // ONE BIT of difference, in the last byte
        let ma = try XCTUnwrap(PairingSeed.derive(seed: a))
        let mb = try XCTUnwrap(PairingSeed.derive(seed: b))
        XCTAssertNotEqual(ma.code, mb.code)
        XCTAssertNotEqual(ma.token, mb.token)
        XCTAssertNotEqual(ma.psk, mb.psk)
        a[0] = 0                                  // silence the unused-mutation warning honestly
        XCTAssertEqual(ma.psk.count, 32)
    }

    /// Shapes the rest of the protocol depends on.
    func testShapes() throws {
        let m = try XCTUnwrap(PairingSeed.derive(seed: [UInt8](repeating: 0xab, count: PairingSeed.seedByteCount)))
        XCTAssertEqual(m.code.count, 8)
        XCTAssertEqual(m.psk.count, 32, "Noise XXpsk3 takes exactly 32 bytes")
        XCTAssertEqual(m.token.count, 36)
        XCTAssertEqual(m.token, m.token.lowercased(), "the session DO compares the token as an exact string")
        // Version and variant nibbles, the two bytes `uuidV4` stamps.
        XCTAssertEqual(m.token[m.token.index(m.token.startIndex, offsetBy: 14)], "4")
        XCTAssertTrue("89ab".contains(m.token[m.token.index(m.token.startIndex, offsetBy: 19)]))
        XCTAssertTrue(m.code.allSatisfy { PairingSeed.alphabet.contains($0) })
    }

    /// A SEED OF THE WRONG LENGTH IS REFUSED, never padded or truncated. Deriving from a short seed
    /// yields a perfectly well-formed pairing window with less entropy than any reader would assume.
    func testWrongSeedLengthIsRefused() {
        // 16 is the legal length now, so the wrong ones moved with it.
        for n in [0, 8, 15, 17, 32, 64] {
            XCTAssertNil(PairingSeed.derive(seed: [UInt8](repeating: 1, count: n)), "\(n) bytes")
            XCTAssertNil(PairingSeed.encode(seed: [UInt8](repeating: 1, count: n)), "\(n) bytes")
        }
    }

    /// The carrier is strict, and the NEGATIVE CONTROLS are the point.
    ///
    /// **LENGTH IS THE DISCRIMINATOR NOW** (2026-09-15): the `ss3.` prefix is gone, so nothing but
    /// the exact shape separates a carrier from any other base64url text. That makes the
    /// wrong-length cases load-bearing rather than tidy — and a 30-character v2 room-token code is
    /// still refused, for the same reason it always was: it is not 22 characters.
    func testCarrierRefusesEverythingElse() throws {
        let seed = [UInt8](repeating: 3, count: PairingSeed.seedByteCount)
        let good = try XCTUnwrap(PairingSeed.encode(seed: seed))
        XCTAssertEqual(good.count, PairingSeed.encodedLength)
        XCTAssertEqual(good.count, 22, "128 bits, bare, in 22 characters")
        XCTAssertEqual(PairingSeed.decode(good), seed)
        XCTAssertEqual(PairingSeed.decode("  \(good)\n"), seed, "a pasted code may carry whitespace")

        XCTAssertNil(PairingSeed.decode(good + "A"), "one character too long")
        XCTAssertNil(PairingSeed.decode(String(good.dropLast())), "one too short")
        XCTAssertNil(PairingSeed.decode("ss3." + good), "the old prefix is not accepted")
        XCTAssertNil(PairingSeed.decode(String(repeating: "!", count: 22)),
                     "right length, not base64url")
        XCTAssertNil(PairingSeed.decode(""), "empty")

        // **THE RETIRED v2 CARRIER MUST NOT DECODE AS A SEED.** Its encoder is gone, so this is the
        // literal 30-character shape it produced rather than a freshly built one — which is the
        // stronger test anyway: it pins the bytes that used to exist rather than whatever an encoder
        // would emit today.
        XCTAssertNil(PairingSeed.decode("1alQfiLoSeeKnQRcgpYMI65ubJGlGQ"),
                     "a v2 pairing code is not a v3 seed")
        // ...and in the other direction, the v3 carrier is now the ONLY opaque form `parsePairing`
        // accepts, so it must parse — §9.1's "cannot be interpreted as" runs one way now.
        XCTAssertNotNil(parsePairing(good), "a v3 carrier is the carrier")
    }
}
